CREATE TABLE `marine-cycle-484213-b4.google_ads.p_ads_Keyword_4435779462`
(
  ad_group_criterion_criterion_id INT64 OPTIONS(description="The ID of the criterion. This field is ignored for mutates."),
  ad_group_id INT64 OPTIONS(description="The ID of the ad group."),
  campaign_id INT64 OPTIONS(description="The ID of the campaign."),
  customer_id INT64 OPTIONS(description="The ID of the customer."),
  ad_group_criterion_approval_status STRING OPTIONS(description="Approval status of the criterion."),
  ad_group_criterion_effective_cpc_bid_micros INT64 OPTIONS(description="The effective CPC (cost-per-click) bid."),
  ad_group_criterion_effective_cpc_bid_source STRING OPTIONS(description="Source of the effective CPC bid."),
  ad_group_criterion_effective_cpm_bid_micros INT64 OPTIONS(description="The effective CPM (cost-per-thousand viewable impressions) bid."),
  ad_group_criterion_final_mobile_urls STRING OPTIONS(description="The list of possible final mobile URLs after all cross-domain redirects."),
  ad_group_criterion_final_url_suffix STRING OPTIONS(description="URL template for appending params to final URL."),
  ad_group_criterion_final_urls STRING OPTIONS(description="The list of possible final URLs after all cross-domain redirects for the ad."),
  ad_group_criterion_keyword_match_type STRING OPTIONS(description="The match type of the keyword."),
  ad_group_criterion_keyword_text STRING OPTIONS(description="The text of the keyword (at most 80 characters and 10 words)."),
  ad_group_criterion_negative BOOL OPTIONS(description="Whether to target (`false`) or exclude (`true`) the criterion. This field is immutable. To switch a criterion from positive to negative, remove then re-add it."),
  ad_group_criterion_position_estimates_estimated_add_clicks_at_first_position_cpc INT64 OPTIONS(description="Estimate of how many clicks per week you might get by changing your keyword bid to the value in first_position_cpc_micros."),
  ad_group_criterion_position_estimates_estimated_add_cost_at_first_position_cpc INT64 OPTIONS(description="Estimate of how your cost per week might change when changing your keyword bid to the value in first_position_cpc_micros."),
  ad_group_criterion_position_estimates_first_page_cpc_micros INT64 OPTIONS(description="The estimate of the CPC bid required for ad to be shown on first page of search results."),
  ad_group_criterion_position_estimates_first_position_cpc_micros INT64 OPTIONS(description="The estimate of the CPC bid required for ad to be displayed in first position, at the top of the first page of search results."),
  ad_group_criterion_position_estimates_top_of_page_cpc_micros INT64 OPTIONS(description="The estimate of the CPC bid required for ad to be displayed at the top of the first page of search results."),
  ad_group_criterion_quality_info_creative_quality_score STRING OPTIONS(description="The performance of the ad compared to other advertisers."),
  ad_group_criterion_quality_info_post_click_quality_score STRING OPTIONS(description="The quality score of the landing page."),
  ad_group_criterion_quality_info_quality_score INT64 OPTIONS(description="The quality score. This field may not be populated if Google does not have enough information to determine a value."),
  ad_group_criterion_quality_info_search_predicted_ctr STRING OPTIONS(description="The click-through rate compared to that of other advertisers."),
  ad_group_criterion_status STRING OPTIONS(description="The status of the criterion."),
  ad_group_criterion_system_serving_status STRING OPTIONS(description="Serving status of the criterion."),
  ad_group_criterion_topic_topic_constant STRING OPTIONS(description="The Topic Constant resource name."),
  ad_group_criterion_tracking_url_template STRING OPTIONS(description="The URL template for constructing a tracking URL."),
  ad_group_criterion_url_custom_parameters STRING OPTIONS(description="The list of mappings used to substitute custom parameter tags in a `tracking_url_template`, `final_urls`, or `mobile_final_urls`."),
  campaign_bidding_strategy STRING OPTIONS(description="Portfolio bidding strategy used by campaign."),
  campaign_bidding_strategy_type STRING OPTIONS(description="The type of bidding strategy. A bidding strategy can be created by setting either the bidding scheme to create a standard bidding strategy or the `bidding_strategy` field to create a portfolio bidding strategy. This field is read-only."),
  campaign_manual_cpc_enhanced_cpc_enabled BOOL OPTIONS(description="Whether bids are to be enhanced based on conversion optimizer data."),
  campaign_percent_cpc_enhanced_cpc_enabled BOOL OPTIONS(description="Adjusts the bid for each auction upward or downward, depending on the likelihood of a conversion. Individual bids may exceed cpc_bid_ceiling_micros, but the average bid amount for a campaign should not.")
)
PARTITION BY DATE(_PARTITIONTIME);
